using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using Rootborn.Game.Common;using Rootborn.Game.World;
namespace Rootborn.Tests.EditMode.World{public sealed class WorldTravelCatalogAssetTests{
private WorldTravelCatalogDefinition Catalog(){var r=AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");Assert.That(r.WorldTravelCatalog,Is.Not.Null);return r.WorldTravelCatalog;}
[Test]public void WORLD_CATALOG_001_NewGameStartsAtRegisteredOwnRoom(){var c=Catalog();Assert.That(c.IsValid,Is.True);Assert.That(c.NewGameDestination.SceneName,Is.EqualTo("House"));Assert.That(c.NewGameSpawnId,Is.EqualTo("house-entry"));}
[Test]public void WORLD_CATALOG_002_SchoolAndReciprocalTownEntriesAreRegistered(){var c=Catalog();Assert.That(c.FindDestination("School").ContainsSpawn("school-entry"),Is.True);Assert.That(c.FindDestination("Town").ContainsSpawn("town-home-entry"),Is.True);Assert.That(c.FindDestination("Town").ContainsSpawn("town-school-entry"),Is.True);Assert.That(c.FindDestination("Beach").ContainsSpawn("beach-top-entry"),Is.True);}
[Test]public void WORLD_CATALOG_003_RegisteredDataUsesLocalAddressables(){var c=Catalog();var settings=AddressableAssetSettingsDefaultObject.Settings;foreach(var d in c.Destinations){var entry=settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(d)));Assert.That(entry,Is.Not.Null);Assert.That(entry.parentGroup.Name,Is.EqualTo("Data"));}Assert.That(settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(c))),Is.Not.Null);}
}}
